class BoxContractState:
    """Methods to access state for the current BoxContract app"""

    def __init__(self, app_client: algokit_utils.AppClient):
        self.app_client = app_client

    @property
    def box(
        self
    ) -> "_BoxState":
            """Methods to access box for the current app"""
            return _BoxState(self.app_client)

class _BoxState:
    def __init__(self, app_client: algokit_utils.AppClient):
        self.app_client = app_client
        
        # Pre-generated mapping of value types to their struct classes
        self._struct_classes: dict[str, typing.Type[typing.Any]] = {
            "LargeStruct": LargeStruct,
            "DynamicArrayInAStruct": DynamicArrayInAStruct
        }

    def get_all(self) -> BoxStateValue:
        """Get all current keyed values from box state"""
        result = self.app_client.state.box.get_all()
        if not result:
            return typing.cast(BoxStateValue, {})

        converted = {}
        for key, value in result.items():
            key_info = self.app_client.app_spec.state.keys.box.get(key)
            struct_class = self._struct_classes.get(key_info.value_type) if key_info else None
            converted[key] = (
                _init_dataclass(struct_class, value) if struct_class and isinstance(value, dict)
                else value
            )
        return typing.cast(BoxStateValue, converted)

    @property
    def box_a(self) -> int:
        """Get the current value of the box_a key in box state"""
        value = self.app_client.state.box.get_value("box_a")
        if isinstance(value, dict) and "uint64" in self._struct_classes:
            return _init_dataclass(self._struct_classes["uint64"], value)  # type: ignore
        return typing.cast(int, value)

    @property
    def box_b(self) -> bytes:
        """Get the current value of the box_b key in box state"""
        value = self.app_client.state.box.get_value("box_b")
        if isinstance(value, dict) and "byte[]" in self._struct_classes:
            return _init_dataclass(self._struct_classes["byte[]"], value)  # type: ignore
        return typing.cast(bytes, value)

    @property
    def box_c(self) -> str:
        """Get the current value of the box_c key in box state"""
        value = self.app_client.state.box.get_value("box_c")
        if isinstance(value, dict) and "string" in self._struct_classes:
            return _init_dataclass(self._struct_classes["string"], value)  # type: ignore
        return typing.cast(str, value)

